<?php ob_start(); $scanCtx=$scanCtx??(function_exists('scan_active_context')?scan_active_context():[]); $scanDisabled=($scanCtx['running']??false)&&!($scanCtx['stale']??false); ?><h1><?= e(t('Sites')) ?></h1><table><tr><th><?= e(t('Name')) ?></th><th><?= e(t('Path')) ?></th><th><?= e(t('Type')) ?></th><th><?= e(t('CMS')) ?></th><th><?= e(t('Last scan')) ?></th><th><?= e(t('Findings')) ?></th><th><?= e(t('Risk')) ?></th><th><?= e(t('Actions')) ?></th></tr><?php foreach($sites as $s): $risk=['','low','medium','high','critical'][(int)($s['risk_score']??0)]??'none'; ?><tr><td><?= e($s['name']) ?></td><td><code><?= e($s['path']) ?></code></td><td><?= e($s['type']) ?></td><td><?= e($s['cms_type']) ?> <?= e($s['cms_version'] ?? '') ?><br><span class="muted"><?= e($s['cms_confidence'] ?? '') ?>%</span></td><td><?= e($s['last_scan_at']) ?></td><td><?= e($s['findings_count']) ?></td><td><?= $risk==='none'?e(t('none')):'<span class="badge '.e($risk).'">'.e(t($risk)).'</span>' ?></td><td><form class="scan-form" method="post" action="/scan/start"><input type="hidden" name="scope" value="site"><input type="hidden" name="value" value="<?= e($s['path']) ?>"><select class="input" name="profile"><?php foreach(['fast','standard','deep'] as $p): ?><option value="<?= e($p) ?>"><?= e(t($p)) ?></option><?php endforeach ?></select><select class="input" name="max_seconds"><option value="300"><?= e(t('5 min')) ?></option><option value="900"><?= e(t('15 min')) ?></option><option value="1800"><?= e(t('30 min')) ?></option><option value="0"><?= e(t('Unlimited/manual')) ?></option></select><button class="btn small" <?= $scanDisabled?'disabled':'' ?>><?= e(t('Scan this site')) ?></button><?php if($scanDisabled): ?><div class="muted"><?= e(t('Another scan is already running: Scan #:id.', ['id'=>$scanCtx['run']['id']??'pending'])) ?> <a href="/scan/active"><?= e(t('View details')) ?></a></div><?php endif ?></form></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
